import platform

import pytest

from conan.test.utils.test_files import temp_folder
from conan.test.utils.tools import TestClient


@pytest.mark.slow
@pytest.mark.tool("bazel", "8.x")
def test_bazel_builds_with_generated_toolchain():
    """Bazel selects the cc_toolchain generated by BazelToolchain and the app runs."""
    client = TestClient(path_with_spaces=False)
    output_root = temp_folder(path_with_spaces=False)
    client.run(f"new bazel_7_exe -d name=myapp -d version=1.0 -d output_root_dir={output_root}")
    client.run("install .")
    client.run_command("bazel build --config=conan-config "
                       "--toolchain_resolution_debug=@bazel_tools//tools/cpp:toolchain_type "
                       "//main:myapp")
    assert "conan/conan_toolchain:target_cc" in client.out
    client.run_command("./bazel-bin/main/myapp")
    assert "myapp/1.0: Hello World Release!" in client.out
